python3 << 'EOF'
import csv
from collections import defaultdict

with open("/app/dataset/hospital_compensation_registry.csv") as f:
    reader = csv.DictReader(f)
    rows = list(reader)

# Final analysis: find all connections between death-related claims and no-claim patients
no_claim = {r['patient_id']: r for r in rows if not r['record_date'].strip()}
claimants = {r['patient_id']: r for r in rows if r['record_date'].strip()}

# Emergency contact map
ec_of = {r['patient_id']: r['emergency_contact_patient_id'].strip() for r in rows}
# Reverse map: who has this person as EC
has_ec = defaultdict(list)
for r in rows:
    has_ec[r['emergency_contact_patient_id'].strip()].append(r['patient_id'])

death_types = {'bereavement compensation', 'life event claim', 'family support adjustment'}
death_claimants = {pid: r for pid, r in claimants.items() if r['compensation_reason'].strip() in death_types}

print("Death claimants and their connections:")
for dc_id, dc in death_claimants.items():
    dc_ec = ec_of[dc_id]
    dc_ln = dc['full_name'].split()[-1]
    print(f"\n{dc_id} ({dc['full_name']}, ${dc['direct_payment_usd']}, {dc['compensation_reason']})")
    print(f"  Emergency contact: {dc_ec} ({rows[int(dc_ec.split('_')[1])-1]['full_name'] if int(dc_ec.split('_')[1]) <= len(rows) else '?'})")

    # Who has this death claimant as their EC?
    if dc_id in has_ec:
        for pid in has_ec[dc_id]:
            if pid in no_claim:
                nr = no_claim[pid]
                same_ln = nr['full_name'].split()[-1] == dc_ln
                print(f"  -> EC of {pid} ({nr['full_name']}) [no claim] {'*** SAME LAST NAME ***' if same_ln else ''}")

    # Who is this death claimant's EC?
    if dc_ec in no_claim:
        nr = no_claim[dc_ec]
        same_ln = nr['full_name'].split()[-1] == dc_ln
        print(f"  -> EC is {dc_ec} ({nr['full_name']}) [no claim] {'*** SAME LAST NAME ***' if same_ln else ''}")

# All no-claim patients with direct EC connection to death claimants
print("\n\n=== Final candidate ranking ===")
candidates = {}
for nc_id, nr in no_claim.items():
    score = 0
    nc_ec = ec_of[nc_id]
    nc_ln = nr['full_name'].split()[-1]

    # Pattern A: no-claim patient's EC is a death claimant
    if nc_ec in death_claimants:
        dc = death_claimants[nc_ec]
        score += 2
        if nc_ln == dc['full_name'].split()[-1]:
            score += 1

    # Pattern B: no-claim patient IS the EC of a death claimant
    for dc_id, dc in death_claimants.items():
        if dc_id in has_ec and nc_id in has_ec[dc_id]:
            score += 2
            if nc_ln == dc['full_name'].split()[-1]:
                score += 1
        if ec_of[dc_id] == nc_id:
            score += 2
            if nc_ln == dc['full_name'].split()[-1]:
                score += 1

    # Pattern C: same last name as death claimant
    for dc_id, dc in death_claimants.items():
        if nc_ln == dc['full_name'].split()[-1]:
            score += 0.5

    if score > 0:
        candidates[nc_id] = (score, nr['full_name'])

for pid, (score, name) in sorted(candidates.items(), key=lambda x: -x[1][0]):
    print(f"{pid} ({name}) - Score: {score}")

print("\n\nTop 3:")
for pid, (score, name) in sorted(candidates.items(), key=lambda x: -x[1][0])[:3]:
    print(f"{pid} ({name}) - Score: {score}")
